#' Win Ratio for Hierarchical Composite Endpoints
#'
#' Analyzes prioritized (hierarchically ordered) composite endpoints using the 
#' win ratio, win odds, and net benefit. Every subject in the index group is 
#' compared with every subject in the reference group. Each pair is classified 
#' as a win, loss, or tie by examining endpoints in order of clinical priority 
#' (e.g. death, then hospitalization, then a continuous biomarker): the first 
#' endpoint that can distinguish the pair decides it. The win ratio is the 
#' number of wins divided by the number of losses. Confidence intervals use 
#' the Dong et al. (2016) analytic variance of the log win ratio; a 
#' subject-level bootstrap option is also provided. This complements 
#' hazard-ratio and RMST analyses when outcomes of differing severity must be 
#' combined and ranked.
#' 
#' @param data The data as a data frame (one row per subject).
#' @param group Two-level grouping variable. The level NOT chosen as the
#'   reference is treated as the index (e.g. treatment) group; the win ratio
#'   expresses the index group's chance of winning relative to the reference
#'   group.
#' @param refLevel The level of the group variable to treat as the reference
#'   (control).
#' @param time1 Time to the primary (highest priority) time-to-event endpoint.
#' @param status1 Event indicator for the primary endpoint.
#' @param eventLevel1 The level of the primary event indicator that denotes
#'   the event occurred.
#' @param time2 Time to a secondary time-to-event endpoint, examined only when
#'   the primary endpoint ties a pair. Leave empty to skip.
#' @param status2 Event indicator for the secondary endpoint.
#' @param eventLevel2 The level of the secondary event indicator that denotes
#'   the event occurred.
#' @param contEndpoint A continuous endpoint used as the lowest-priority
#'   tiebreaker, examined only when all time-to-event endpoints tie a pair.
#' @param contDirection Whether a higher or lower value of the continuous
#'   endpoint is the better outcome.
#' @param contTol Minimum absolute difference on the continuous endpoint
#'   required to declare a win or loss; smaller differences are counted as ties.
#' @param conf_level Confidence level for interval estimates.
#' @param ciMethod Method for the win ratio confidence interval and p-value.
#' @param bootstrap_n Number of bootstrap replicates when the bootstrap CI
#'   method is selected.
#' @param showWinOdds Report the win odds (ties split evenly), an estimand
#'   defined even when there are no losses.
#' @param showNetBenefit Report the net benefit (proportion of wins minus
#'   proportion of losses).
#' @param showComponents Break down wins, losses and ties by the endpoint that
#'   decided each pair.
#' @param showPlot Display a stacked bar of the win, loss and tie proportions.
#' @param showSummary Display a plain-language summary of the results.
#' @param showExplanation Display an explanation of the win ratio methodology.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mainTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$countsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$componentsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$mainTable$asDF}
#'
#' \code{as.data.frame(results$mainTable)}
#'
#' @export
winratio <- function(
    data,
    group,
    refLevel,
    time1,
    status1,
    eventLevel1,
    time2 = NULL,
    status2 = NULL,
    eventLevel2,
    contEndpoint = NULL,
    contDirection = "higher",
    contTol = 0,
    conf_level = 0.95,
    ciMethod = "analytic",
    bootstrap_n = 1000,
    showWinOdds = TRUE,
    showNetBenefit = TRUE,
    showComponents = TRUE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("winratio requires jmvcore to be installed (restart may be required)")

    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(time1)) time1 <- jmvcore::resolveQuo(jmvcore::enquo(time1))
    if ( ! missing(status1)) status1 <- jmvcore::resolveQuo(jmvcore::enquo(status1))
    if ( ! missing(time2)) time2 <- jmvcore::resolveQuo(jmvcore::enquo(time2))
    if ( ! missing(status2)) status2 <- jmvcore::resolveQuo(jmvcore::enquo(status2))
    if ( ! missing(contEndpoint)) contEndpoint <- jmvcore::resolveQuo(jmvcore::enquo(contEndpoint))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(time1), time1, NULL),
            `if`( ! missing(status1), status1, NULL),
            `if`( ! missing(time2), time2, NULL),
            `if`( ! missing(status2), status2, NULL),
            `if`( ! missing(contEndpoint), contEndpoint, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- winratioOptions$new(
        group = group,
        refLevel = refLevel,
        time1 = time1,
        status1 = status1,
        eventLevel1 = eventLevel1,
        time2 = time2,
        status2 = status2,
        eventLevel2 = eventLevel2,
        contEndpoint = contEndpoint,
        contDirection = contDirection,
        contTol = contTol,
        conf_level = conf_level,
        ciMethod = ciMethod,
        bootstrap_n = bootstrap_n,
        showWinOdds = showWinOdds,
        showNetBenefit = showNetBenefit,
        showComponents = showComponents,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- winratioClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

